import React, { useState, useEffect } from "react";
import { getActivityList } from "../../utils/api";
import toast from "react-hot-toast";

const AttendanceTable = () => {
  const [activities, setActivities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      try {
        const activities = await getActivityList();
        setActivities(activities);
      } catch (err) {
        console.error(err);
        toast.error("載入失敗");
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  const Skeleton = () => (
    <>
      {/* 桌面版骨架 */}
      <div className="hidden sm:block animate-pulse">
        <table className="min-w-full text-sm text-white">
          <thead>
            <tr>
              <th className="p-2 text-left">活動資訊</th>
              <th className="p-2 text-left">活動 ID</th>
            </tr>
          </thead>
          <tbody>
            {Array.from({ length: 5 }).map((_, idx) => (
              <tr key={idx}>
                <td className="p-2">
                  <div className="h-4 bg-gray-300 bg-opacity-30 rounded w-3/4"></div>
                </td>
                <td className="p-2">
                  <div className="h-4 bg-gray-300 bg-opacity-30 rounded w-1/2"></div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 手機版骨架 */}
      <div className="block sm:hidden animate-pulse space-y-4">
        {Array.from({ length: 5 }).map((_, idx) => (
          <div key={idx} className="bg-black bg-opacity-40 rounded p-3">
            <div className="h-4 bg-gray-300 bg-opacity-30 rounded w-2/3 mb-2"></div>
            <div className="h-3 bg-gray-300 bg-opacity-30 rounded w-1/3"></div>
          </div>
        ))}
      </div>
    </>
  );

  return (
    <div className="bg-white bg-opacity-20 backdrop-blur-lg rounded-lg p-6 shadow-lg">
      <h2 className="text-xl font-bold mb-4">活動列表</h2>

      {loading ? (
        <Skeleton />
      ) : (
        <>
          <div className="hidden sm:block">
            <table className="min-w-full text-sm text-white">
              <thead>
                <tr>
                  <th className="p-2 text-left">活動資訊</th>
                  <th className="p-2 text-left">活動 ID</th>
                </tr>
              </thead>
              <tbody>
                {activities.map((item, idx) => (
                  <tr key={idx}>
                    <td className="p-2">{item.label}</td>
                    <td className="p-2">{item.value}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* 手機版 */}
          <div className="block sm:hidden space-y-4">
            {activities.map((item, idx) => (
              <div key={idx} className="bg-black bg-opacity-60 rounded p-3">
                <div className="font-bold mb-1">{item.label}</div>
                <div className="text-xs">ID: {item.value}</div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default AttendanceTable;
