// components/Layout.js
import React, { useState } from "react";
import { Outlet, Link } from "react-router-dom";
import Drawer from "@mui/material/Drawer";
import IconButton from "@mui/material/IconButton";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faBars } from "@fortawesome/free-solid-svg-icons";
import { List, ListItem, ListItemText } from "@mui/material";

const Layout = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const toggleDrawer = (open) => () => setDrawerOpen(open);

  return (
    <>
      {/* Drawer Button */}
      <div className="absolute top-4 left-4 z-50">
        <IconButton onClick={toggleDrawer(true)} style={{ color: "white" }}>
          <FontAwesomeIcon className="text-sm text-white" icon={faBars} />
        </IconButton>
      </div>

      {/* Drawer */}
      <Drawer
        anchor="left"
        open={drawerOpen}
        onClose={toggleDrawer(false)}
        PaperProps={{
          sx: {
            backgroundColor: "rgba(0, 0, 0, 0.6)",
            color: "white",
            backdropFilter: "blur(5px)",
          },
        }}
      >
        <div
          role="presentation"
          onClick={toggleDrawer(false)}
          onKeyDown={toggleDrawer(false)}
          style={{ width: 250 }}
        >
          <List>
            <ListItem button component={Link} to="/">
              <ListItemText primary="首頁" />
            </ListItem>
            <ListItem button component={Link} to="/leaderboard">
              <ListItemText primary="排行榜" />
            </ListItem>
            <ListItem button component={Link} to="/members">
              <ListItemText primary="清冊" />
            </ListItem>
            <ListItem button component={Link} to="/monthlystats">
              <ListItemText primary="每月統計" />
            </ListItem>
            <ListItem button component={Link} to="/eventhistory">
              <ListItemText primary="活動紀錄" />
            </ListItem>
          </List>
        </div>
      </Drawer>

      {/* 內容區域 */}
      <Outlet />
    </>
  );
};

export default Layout;
