import React, { useState, useEffect } from "react";
import styles from "./FifteenPuzzle.module.css";

const GRID_SIZE = 4;
const TILE_SIZE = 60 + 3; // tile size + gap (px)
const TILE_COUNT = GRID_SIZE * GRID_SIZE;

const isSolvable = (tiles) => {
  let inversions = 0;
  for (let i = 0; i < tiles.length; i++) {
    for (let j = i + 1; j < tiles.length; j++) {
      if (tiles[i] && tiles[j] && tiles[i] > tiles[j]) inversions++;
    }
  }
  const emptyRow = Math.floor(tiles.indexOf(0) / GRID_SIZE);
  return (inversions + emptyRow) % 2 === 0;
};

const isSolved = (tiles) =>
  tiles.every((tile, idx) => tile === (idx + 1) % TILE_COUNT);

const shuffleTiles = () => {
  let tiles;
  do {
    tiles = [...Array(TILE_COUNT).keys()];
    for (let i = tiles.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [tiles[i], tiles[j]] = [tiles[j], tiles[i]];
    }
  } while (!isSolvable(tiles));
  return tiles;
};

const FifteenPuzzle = () => {
  const [tiles, setTiles] = useState([]);
  const [won, setWon] = useState(false);
  const viewportHeight = window.innerHeight;

  useEffect(() => {
    setTiles(shuffleTiles());
  }, []);

  const moveTile = (index) => {
    const empty = tiles.indexOf(0);
    const isAdjacent =
      [1, -1, GRID_SIZE, -GRID_SIZE].includes(index - empty) &&
      (Math.floor(index / GRID_SIZE) === Math.floor(empty / GRID_SIZE) ||
        index % GRID_SIZE === empty % GRID_SIZE);

    if (isAdjacent) {
      const newTiles = [...tiles];
      [newTiles[index], newTiles[empty]] = [newTiles[empty], newTiles[index]];
      setTiles(newTiles);
      if (isSolved(newTiles)) setWon(true);
    }
  };

  const getTileStyle = (index) => {
    const row = Math.floor(index / GRID_SIZE);
    const col = index % GRID_SIZE;
    return {
      transform: `translate(${col * TILE_SIZE}px, ${row * TILE_SIZE}px)`,
    };
  };

  return (
    <div
      className="relative"
      style={{
        height: `${viewportHeight}px`,
        backgroundImage: `url(${process.env.PUBLIC_URL}/atlantis-background.png)`,
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <div className={styles.overlay}>
        <h2 style={{ fontSize: 16, marginBottom: 8 }}>
          {won ? "🎉 你贏了！" : "15 Puzzle Game"}
        </h2>
        <div className={styles.board}>
          {tiles.map((tile, index) => {
            if (tile === 0) return null;
            const tileIndex = tiles.indexOf(tile);
            return (
              <div
                key={tile}
                className={styles.tile}
                onClick={() => moveTile(tileIndex)}
                style={getTileStyle(tileIndex)}
              >
                {tile}
              </div>
            );
          })}
        </div>
        <button
          className={styles.button}
          onClick={() => {
            setTiles(shuffleTiles());
            setWon(false);
          }}
        >
          🔄 重排
        </button>
      </div>
    </div>
  );
};

export default FifteenPuzzle;
