import { HashRouter as Router, Route, Routes } from "react-router-dom";
import React, { useEffect } from "react";
import HomePage from "./pages/HomePage";
import "./styles/output.css";
import LeaderBoard from "./pages/LeaderBoard";
import Members from "./pages/Members";
import MonthlyStats from "./pages/MonthlyStats";
import EventHistory from "./pages/EventHistory";
import Layout from "./components/Layout";
import FifteenPuzzle from "./pages/FifteenPuzzle";

// 管理用頁面
import EventDashboard from "./pages/EventDashboard/EventDashboard";

import { Toaster } from "react-hot-toast";

function App() {
  useEffect(() => {
    const isiOS = /iP(ad|hone|od)/.test(navigator.userAgent);

    if (isiOS) {
      const preventPinch = (e) => {
        if (e.scale !== 1) {
          e.preventDefault();
        }
      };

      const preventDoubleTap = (e) => {
        if (e.touches.length > 1) {
          e.preventDefault();
        }
      };

      document.addEventListener("touchmove", preventPinch, { passive: false });
      document.addEventListener("touchstart", preventDoubleTap, {
        passive: false,
      });

      return () => {
        document.removeEventListener("touchmove", preventPinch);
        document.removeEventListener("touchstart", preventDoubleTap);
      };
    }
  }, []);
  return (
    <div className="hidden-scrollbar">
      <Toaster
        toastOptions={{
          style: {
            background: "#333",
            color: "#fff",
          },
        }}
      />
      <Router basename="/">
        <Routes>
          <Route path="/" element={<Layout />}>
            <Route path="/" element={<HomePage />} />
            <Route path="/leaderboard" element={<LeaderBoard />} />
            <Route path="/members" element={<Members />} />
            <Route path="/monthlystats" element={<MonthlyStats />} />
            <Route path="/eventhistory" element={<EventHistory />} />
            <Route path="/eventdashboard" element={<EventDashboard />} />
            <Route path="/fifteenpuzzle" element={<FifteenPuzzle />} />
          </Route>
        </Routes>
      </Router>
    </div>
  );
}

export default App;
