// 設定用
// 讀取使用者
export const getUserList = async () => {
  const response = await axios.post(
    API_URL,
    JSON.stringify({
      route_type: "get_select_list",
      query_key: "get_users",
    }),
    headers
  );
  const result = response.data[0]?.result;
  return Array.isArray(result) ? result : [];
};

