// 新增活動
export const createActivity = async ({
  activity_date,
  user_id,
  activity_place,
  activity_name,
  activity_type,
}) => {
  const payload = JSON.stringify({
    route_type: "add_activity_main",
    data: {
      activity_date,
      user_id,
      activity_place,
      activity_name,
      activity_type,
    },
  });
  const response = await axios.post(API_URL, payload, headers);
  return response.data;
};

// 新增出席者
export const addParticipant = async ({ activity_key, user_id }) => {
  const payload = JSON.stringify({
    route_type: "add_activity_record",
    data: {
      activity_key,
      user_id,
    },
  });
  const response = await axios.post(API_URL, payload, headers);
  return response.data;
};

export const buildUserMap = (userList) => {
  const map = {};
  userList.forEach((user) => {
    map[user.value] = user.label;
  });
  return map;
};
