import React, { useEffect, useState, useCallback, useRef } from "react";
import { getMonthlyStats } from "../utils/api";
import { toast } from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faRotate } from "@fortawesome/free-solid-svg-icons";

const MonthlyStats = () => {
  const [headers, setHeaders] = useState([]);
  const [rows, setRows] = useState([]);
  const [timestamp, setTimestamp] = useState(null);
  const [loading, setLoading] = useState(false);
  const viewportHeight = window.innerHeight;

  const clickCountRef = useRef(0);

  const CACHED_MONTHLYSTATS_HEADERS = "monthlyStatsHeaders";
  const CACHED_MONTHLYSTATS_ROWS = "monthlyStatsRows";
  const CACHED_MONTHLYSTATS_TIMESTAMP = "monthlyStatsTimestamp";
  const REFRESH_INTERVAL = 300000;

  const fetchTableData = useCallback(async () => {
    setLoading(true);
    try {
      const parsedResult = await getMonthlyStats();

      setHeaders(parsedResult.headers);
      setRows(parsedResult.rows);

      localStorage.setItem(
        CACHED_MONTHLYSTATS_HEADERS,
        JSON.stringify(parsedResult.headers)
      );
      localStorage.setItem(
        CACHED_MONTHLYSTATS_ROWS,
        JSON.stringify(parsedResult.rows)
      );
      localStorage.setItem(
        CACHED_MONTHLYSTATS_TIMESTAMP,
        Date.now().toString()
      );
      setTimestamp(new Date());
    } catch (error) {
      console.error("Error fetching monthlystats data", error);
      toast.error("資料取得失敗");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const cachedData_headers = localStorage.getItem(
      CACHED_MONTHLYSTATS_HEADERS
    );
    const cachedData_rows = localStorage.getItem(CACHED_MONTHLYSTATS_ROWS);
    const cachedTimestamp = localStorage.getItem(CACHED_MONTHLYSTATS_TIMESTAMP);
    if (cachedData_headers && cachedData_rows && cachedTimestamp) {
      setHeaders(JSON.parse(cachedData_headers));
      setRows(JSON.parse(cachedData_rows));
      setTimestamp(new Date(parseInt(cachedTimestamp)));
    } else {
      fetchTableData();
    }
  }, [fetchTableData]);

  const handleRefresh = () => {
    const cachedTimestamp = localStorage.getItem(CACHED_MONTHLYSTATS_TIMESTAMP);
    const currentTime = Date.now();

    if (
      !cachedTimestamp ||
      currentTime - parseInt(cachedTimestamp) > REFRESH_INTERVAL
    ) {
      fetchTableData();
      clickCountRef.current = 0;
    } else {
      clickCountRef.current += 1;
      if (clickCountRef.current <= 3) {
        toast.error("刷新次數過於頻繁，請稍後再試。");
      } else if (clickCountRef.current <= 6) {
        toast.error("就說了稍後再試");
      } else {
        toast.error("＾＿＾");
      }
    }
  };

  const formatTimestamp = (date) => (date ? date.toLocaleString() : "尚未更新");

  const Skeleton = () => (
    <div className="animate-pulse">
      {Array.from({ length: 5 }).map((_, rowIndex) => (
        <tr key={rowIndex} className="border-b border-gray-700">
          {Array.from({ length: headers.length || 12 }).map((_, colIndex) => (
            <td
              key={colIndex}
              className="p-2 h-8 text-center w-20 bg-gray-800"
            ></td>
          ))}
        </tr>
      ))}
    </div>
  );

  return (
    <div
      className="relative"
      style={{
        height: `${viewportHeight}px`,
        backgroundImage: `url(${process.env.PUBLIC_URL}/atlantis-background.png)`,
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <div className="absolute inset-0 bg-black bg-opacity-60 flex justify-center items-center">
        <div className="max-w-full p-6 text-white">
          <h1 className="text-2xl font-bold text-center mb-3">月統計表</h1>
          <p className="text-center mb-4 text-xs">
            數據更新時間為：{formatTimestamp(timestamp)}{" "}
            <button onClick={handleRefresh} className="ml-2">
              <FontAwesomeIcon
                className={`text-xl text-white ${
                  loading ? "animate-spin" : ""
                }`}
                icon={faRotate}
              />
            </button>
          </p>
          <div
            className="overflow-x-auto overflow-y-auto rounded-lg shadow-lg bg-white bg-opacity-20 backdrop-blur-lg"
            style={{ maxHeight: `${viewportHeight * 0.8}px` }}
          >
            <table className="min-w-max text-xs text-white table-fixed">
              <thead className="sticky top-0 z-50 bg-black bg-opacity-80">
                <tr>
                  {headers.map((header, idx) => (
                    <th
                      key={idx}
                      className={`p-2 border-b border-gray-500 text-center ${
                        idx === 0
                          ? "sticky left-0 w-28 min-w-[7rem] bg-black bg-opacity-80"
                          : "p-2 text-center w-20"
                      }`}
                    >
                      {header}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <Skeleton />
                ) : (
                  Array.isArray(rows) &&
                  rows.map((row, idx) => (
                    <tr
                      key={idx}
                      className="border-b border-gray-700 hover:bg-white hover:bg-opacity-10 transition"
                    >
                      <td className="p-2 text-center sticky left-0 z-10 bg-black bg-opacity-80 ">
                        <div className="overflow-hidden whitespace-nowrap text-ellipsis w-24">
                          {row.userName}
                        </div>
                      </td>
                      <td className="p-2 text-center w-20">{row.speech_3}</td>
                      <td className="p-2 text-center w-20">{row.speech_2}</td>
                      <td className="p-2 text-center w-20">{row.speech_1}</td>
                      <td className="p-2 text-center w-20">{row.speech_0}</td>
                      <td className="p-2 text-center w-20">{row.att_2}</td>
                      <td className="p-2 text-center w-20">{row.att_1}</td>
                      <td className="p-2 text-center w-20">{row.att_0}</td>
                      <td className="p-2 text-center w-16">
                        {row.danger_next_month ? "⚠️" : "-"}
                      </td>
                      <td className="p-2 text-center w-16">
                        {row.goodbye_this_month ? "👋" : "-"}
                      </td>
                      <td className="p-2 text-center w-20">{row.score_H1}</td>
                      <td className="p-2 text-center w-20">{row.score_H2}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MonthlyStats;
