import React, { useState, useEffect } from "react";
import { getUserList, getActivityList, addParticipant } from "../../utils/api";
import toast from "react-hot-toast";

const ParticipantForm = () => {
  const [participant, setParticipant] = useState("");
  const [selectedActivity, setSelectedActivity] = useState("");
  const [participants, setParticipants] = useState([]);
  const [activities, setActivities] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectLoading, setSelectLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      try {
        const userList = await getUserList();
        const activityList = await getActivityList();
        setParticipants([{ label: "請選擇", value: "" }, ...userList]);
        setActivities([{ label: "請選擇", value: "" }, ...activityList]);
      } catch (err) {
        console.error(err);
        toast.error("資料讀取失敗");
      } finally {
        setSelectLoading(false);
      }
    }
    fetchData();
  }, []);

  const handleSubmit = async () => {
    if (!selectedActivity || !participant) {
      toast.error("請完整選擇活動與出席者");
      return;
    }
    try {
      setLoading(true);
      await addParticipant({
        activity_key: selectedActivity,
        user_id: participant,
      });
      toast.success("出席者已成功新增！");
      setParticipant("");
      setSelectedActivity("");
    } catch (err) {
      console.error(err);
      toast.error("新增失敗");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white bg-opacity-20 backdrop-blur-lg rounded-lg p-6 shadow-lg">
      <h2 className="text-xl font-bold mb-4">新增出席者</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
        <div>
          <label className="block mb-1 text-sm">活動名稱</label>
          <select
            className="p-2 rounded w-full text-black h-12"
            value={selectedActivity}
            onChange={(e) => setSelectedActivity(e.target.value)}
            disabled={selectLoading}
          >
            {selectLoading ? (
              <option>載入中...</option>
            ) : (
              activities.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))
            )}
          </select>
        </div>

        <div>
          <label className="block mb-1 text-sm">出席者</label>
          <select
            className="p-2 rounded w-full text-black h-12"
            value={participant}
            onChange={(e) => setParticipant(e.target.value)}
            disabled={selectLoading}
          >
            {selectLoading ? (
              <option>載入中...</option>
            ) : (
              participants.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))
            )}
          </select>
        </div>
      </div>

      <div className="mt-4">
        <button
          className={`bg-blue-500 px-4 py-2 rounded text-white w-full sm:w-auto ${
            loading ? "opacity-50" : ""
          }`}
          onClick={handleSubmit}
          disabled={loading || selectLoading}
        >
          {loading ? "處理中..." : "新增"}
        </button>
      </div>
    </div>
  );
};

export default ParticipantForm;
